def icon(name='arrow'):
    paths={'arrow':'<path d="M5 12h14m-5-5 5 5-5 5"/>','up':'<path d="M5 19 19 5M5 5h14v14"/>','check':'<path d="m5 12 4 4L19 6"/>','plus':'<path d="M12 5v14M5 12h14"/>','cup':'<path d="M4 8h12v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8Zm12 1h2a3 3 0 0 1 0 6h-2M8 3v2m4-2v2"/>','temperature':'<path d="M10 14V5a2 2 0 0 1 4 0v9a4 4 0 1 1-4 0Z"/><path d="M12 10v8m6-11h3m-3 4h2"/>','grind':'<path d="M6 4h12l-2 7H8L6 4Zm2 7h8v5H8zm-2 5h12v5H6zm13-9h3v5"/>','dose':'<path d="M5 11h14l2 10H3l2-10Zm3-7h8l-1 7H9L8 4Zm2 12h4"/>','time':'<circle cx="12" cy="14" r="7"/><path d="M12 10v4l3 2M9 3h6m-3 0v4m6-1 2 2"/>'}
    return f'<svg viewBox="0 0 24 24" aria-hidden="true">{paths[name]}</svg>'

from catalog import load_catalog
