DISCOUNT=CATALOG['student_discount_percent']
def student_price(bean):return (bean['price_ntd']*(100-DISCOUNT)+50)//100
uniform_specs=len({(b['weight_g'],b['price_ntd']) for b in BEANS})==1
price_summary=f"{BEANS[0]['weight_g']}g / NT${BEANS[0]['price_ntd']:,}" if uniform_specs else '規格與售價見各豆款'
student_summary=f"學生九折・NT${student_price(BEANS[0]):,}／包" if uniform_specs and DISCOUNT==10 else f"學生優惠 {DISCOUNT}%・價格見各豆款"

